import { execSync, spawnSync } from 'child_process';
import { mkdirSync } from 'fs';
import { get } from 'https';

const repoUrl = process.argv[2] || '';
if (!repoUrl) {
  console.error('Usage: node gitart-2026.mjs <repo-url>');
  process.exit(1);
}

// Validate URL before doing anything — must be a GitHub HTTPS URL
try {
  const u = new URL(repoUrl);
  if (u.protocol !== 'https:' || u.hostname !== 'github.com') {
    console.error('❌ Repo URL must be a GitHub HTTPS URL (https://github.com/...)');
    process.exit(1);
  }
} catch {
  console.error('❌ Invalid repo URL:', repoUrl);
  process.exit(1);
}

// Resolve the commit author email: baked-in value, GITART_EMAIL, or git config
const cleanEmail = (e) => (e || '').trim().replace(/[^a-zA-Z0-9@._+\-]/g, '');
const readGitEmail = () => {
  const r = spawnSync('git', ['config', '--get', 'user.email'], { encoding: 'utf8' });
  return r.status === 0 ? r.stdout : '';
};
const authorEmail = cleanEmail('') || cleanEmail(process.env.GITART_EMAIL) || cleanEmail(readGitEmail());
if (!authorEmail) {
  console.error('❌ No author email found. Commits must use your GitHub email to show on your graph.');
  console.error('   Fix: git config --global user.email "you@example.com"   (or set GITART_EMAIL)');
  process.exit(1);
}

const workDir = 'gitart-canvas-2026';
mkdirSync(workDir, { recursive: true });
process.chdir(workDir);

// exec: for hardcoded commands only (no user input)
const exec = (cmd) => execSync(cmd, { stdio: 'pipe', encoding: 'utf8' });
// spawn: for commands that include user-supplied values (array args = no shell injection)
const git = (...args) => {
  const r = spawnSync('git', args, { stdio: 'pipe', encoding: 'utf8' });
  if (r.status !== 0) throw Object.assign(new Error(r.stderr || r.stdout || 'git failed'), { stderr: r.stderr });
  return r.stdout;
};

const check = (label, ok, detail = '') => {
  const icon = ok ? '✅' : '❌';
  console.log(`  ${icon} ${label}${detail ? ' — ' + detail : ''}`);
  return ok;
};

// ── Step 1: Init repo ────────────────────────────────────────────
console.log('\n[1/4] Setting up local repo...');
exec('git init -q');
try { exec('git checkout -b main'); } catch { exec('git checkout main'); }
git('config', 'user.email', authorEmail);
git('config', 'user.name', 'GitArt');
check('Repo initialized', true);
check('Author email set', true, authorEmail);

